def page(title,description,active,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#14242b"><title>{escape(title)}</title><meta name="description" content="{escape(description,quote=True)}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/site-v6.css"><script src="/assets/site-v6.js" defer></script><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"></head><body data-page="{active}"><a href="#main" class="skip-link">Skip to content</a>{header(active)}<main id="main">{body}</main>{footer()}<div id="lightbox" class="lightbox" role="dialog" aria-modal="true" aria-label="Photo viewer" aria-hidden="true"><button id="lightbox-close" type="button" aria-label="Close photo viewer">✕</button><button id="lightbox-prev" type="button" aria-label="Previous image">←</button><figure><img id="lightbox-img" src="" alt=""><figcaption id="lightbox-caption"></figcaption></figure><button id="lightbox-next" type="button" aria-label="Next image">→</button></div></body></html>'''
def photo_item(src,alt,tag,klass='',fallback=None):
 return f'<button type="button" class="gallery-photo {klass}" data-gallery-image aria-label="View photo: {escape(alt,quote=True)}">{img(src,alt,fallback=fallback)}<span class="gallery-label">{tag}</span><span class="gallery-expand" aria-hidden="true">↗</span></button>'

